### Describe the bug

I'm trying to switch to swc for our emits completely in Deno, but I ran into this bug. The mapping of source maps has the width of multi-byte characters too long.

For exmaple:

![image](https://user-images.githubusercontent.com/1609021/177885924-db9b537d-902e-40df-815a-647bdfa9795f.png)

...is mapped to two characters:

![image](https://user-images.githubusercontent.com/1609021/177885941-31a20c33-9dbd-4bf4-aa4c-292f749631bc.png)

Or this comment:

![image](https://user-images.githubusercontent.com/1609021/177886004-4dd582cb-8586-4ef5-afae-38215e2e0e71.png)

Mapped to:

![image](https://user-images.githubusercontent.com/1609021/177886020-951831d9-d602-4b84-9105-34c0877b9f3d.png)


### Input code

```typescript
// This entire interface should be completely ignored by the coverage tool.
export interface Complex {
  // These comments should be ignored.
  foo: string;

  // But this is a stub, so this isn't really documentation.
  bar: string;

  // Really all these are doing is padding the line count.
  baz: string;
}

// Lets add some wide characters to ensure that the absolute byte offsets are
// being matched properly.
//
// 패딩에 대한 더 많은 문자.
function dependency(
  foo: string,
  bar: string,
  baz: string,
): Complex {
  return {
    foo,
    bar,
    baz,
  };
}

// Again just more wide characters for padding.
//
// 良い対策のためにいくつかのユニコード文字を投げる。
export function complex(
  foo: string,
  bar: string,
  baz: string,
): Complex {
  return dependency(
    foo,
    bar,
    baz,
  );
}

// And yet again for good measure.
// 更多用於填充的字元。
export function unused(
  foo: string,
  bar: string,
  baz: string,
): Complex {
  return complex(
    foo,
    bar,
    baz,
  );
}

// Using a non-ascii name again to ensure that the byte offsets match up
// correctly.
export const π = Math.PI;

// And same applies for this one, this one is unused and will show up in
// lacking coverage.
export function ƒ(): number {
  return (
    0
  );
}

// This arrow function should also show up as uncovered.
console.log("%s", () => 1);

// Make sure emojis work properly
console.log("📣❓");
```


### Config

```json
{
  "$schema": "https://json.schemastore.org/swcrc",
  "jsc": {
    "parser": {
      "syntax": "typescript"
    },
    "target": "es2020",
    "loose": false,
    "externalHelpers": false
  },
  "sourceMaps": true
}
```


